// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;

    function setUp() public { c = new MyContract(); }

    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.deal(address(c), amount);
        Receiver r = new Receiver();
        uint256 before = address(r).balance;
        // owner of c is this test contract (deployer)
        try c.sendTo(address(r), amount) {
            assertTrue(address(r).balance - before == amount, "authorized send must transfer amount");
        } catch {
            assertTrue(false, "call must not revert for funded owner");
        }
    }
}

contract Receiver {
    receive() external payable {}
}
